"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import {
  type ChartStatus,
  ChartState,
  type Candle,
  Keyframes,
  MARKET_RANGES,
  type MarketRange,
  formatMoney,
  formatSignedPct,
  useElementWidth,
  usePrefersReducedMotion,
} from "@/components/moneytrees/charts/chart-engine";
import {
  AreaSeries,
  CandleSeries,
  ChartDefs,
  type ChartLayout,
  HoverBand,
  HoverOverlay,
  LastPriceMarker,
  MarketChartHeader,
  PriceAxis,
  PriceGrid,
  type PriceSummary,
  TimeAxis,
  type Variant,
  VolumeSeries,
  initialRangeLabel,
  layoutFor,
  useAreaGeometry,
  useHover,
  useLiveTicks,
  useMaxVolume,
  usePriceScale,
  usePriceSummary,
  useRangeView,
  useTimeTicks,
} from "@/components/moneytrees/charts/market-chart-parts";

export interface MarketChartProps {
  className?: string;
  data: Candle[];
  symbol?: string;
  name?: string;
  variant?: Variant;
  showVolume?: boolean;
  hollowUp?: boolean;
  ranges?: MarketRange[];
  defaultRange?: string;
  showRangeSelector?: boolean;
  live?: boolean;
  height?: number;
  compactPrice?: boolean;
  status?: ChartStatus;
  onRetry?: () => void;
}

interface CanvasProps {
  svgRef: React.RefObject<SVGSVGElement | null>;
  symbol: string;
  name: string;
  variant: Variant;
  showVolume: boolean;
  hollowUp: boolean;
  live: boolean;
  reduce: boolean;
  rangeLabel: string;
  uid: string;
  view: Candle[];
  layout: ChartLayout;
  cx: (i: number) => number;
  priceY: (v: number) => number;
  priceAt: (y: number) => number;
  priceTicks: number[];
  timeTicks: number[];
  maxVolume: number;
  summary: PriceSummary;
  hoverIndex: number | null;
  hoverY: number | null;
  pointerToIndex: (clientX: number, clientY: number) => void;
  clearHover: () => void;
  onKeyDown: (event: React.KeyboardEvent) => void;
  linePath: string;
  areaPath: string;
  baselineY: number;
}

function MarketChartCanvas({
  svgRef,
  symbol,
  name,
  variant,
  showVolume,
  hollowUp,
  live,
  reduce,
  rangeLabel,
  uid,
  view,
  layout,
  cx,
  priceY,
  priceAt,
  priceTicks,
  timeTicks,
  maxVolume,
  summary,
  hoverIndex,
  hoverY,
  pointerToIndex,
  clearHover,
  onKeyDown,
  linePath,
  areaPath,
  baselineY,
}: CanvasProps) {
  const { w, h } = layout;
  const { last, delta, lastColor } = summary;
  const n = view.length;
  const introKey = `${rangeLabel}-${variant}`;
  const hovered = hoverIndex != null ? view[hoverIndex] : undefined;

  return (
    <svg
      ref={svgRef}
      width={w}
      height={h}
      viewBox={`0 0 ${w} ${h}`}
      className="block w-full touch-pan-y select-none overflow-visible"
      role="img"
      aria-label={`${symbol} ${name} price chart, ${rangeLabel} range. ${formatMoney(
        last?.close ?? 0,
      )}, ${formatSignedPct(delta)}.`}
      tabIndex={0}
      onKeyDown={onKeyDown}
      onPointerMove={(e) => pointerToIndex(e.clientX, e.clientY)}
      onPointerDown={(e) => pointerToIndex(e.clientX, e.clientY)}
      onPointerLeave={clearHover}
      onBlur={clearHover}
    >
      <ChartDefs uid={uid} baselineY={baselineY} layout={layout} />
      <PriceGrid priceTicks={priceTicks} priceY={priceY} layout={layout} />
      <PriceAxis
        priceTicks={priceTicks}
        priceY={priceY}
        layout={layout}
        last={last}
        hoverY={hoverY}
      />
      <TimeAxis timeTicks={timeTicks} view={view} cx={cx} layout={layout} />

      {hoverIndex != null && hovered ? (
        <HoverBand index={hoverIndex} cx={cx} layout={layout} />
      ) : null}

      {variant === "area" ? (
        <AreaSeries
          key={introKey}
          uid={uid}
          reduce={reduce}
          areaPath={areaPath}
          linePath={linePath}
          baselineY={baselineY}
          layout={layout}
        />
      ) : (
        <CandleSeries
          key={introKey}
          view={view}
          cx={cx}
          priceY={priceY}
          layout={layout}
          hoverIndex={hoverIndex}
          reduce={reduce}
          hollowUp={hollowUp}
        />
      )}

      {showVolume ? (
        <VolumeSeries
          key={`${introKey}-vol`}
          view={view}
          cx={cx}
          layout={layout}
          hoverIndex={hoverIndex}
          reduce={reduce}
          maxVolume={maxVolume}
        />
      ) : null}

      {last ? (
        <LastPriceMarker
          last={last}
          lastColor={lastColor}
          live={live}
          reduce={reduce}
          n={n}
          cx={cx}
          priceY={priceY}
          layout={layout}
        />
      ) : null}

      {hoverIndex != null && hovered ? (
        <HoverOverlay
          index={hoverIndex}
          candle={hovered}
          hoverY={hoverY}
          reduce={reduce}
          cx={cx}
          priceY={priceY}
          priceAt={priceAt}
          layout={layout}
        />
      ) : null}
    </svg>
  );
}

export function MarketChart({
  className,
  data,
  symbol = "SOL",
  name = "Solana",
  variant = "candles",
  showVolume = true,
  hollowUp = false,
  ranges = MARKET_RANGES,
  defaultRange = "3M",
  showRangeSelector = true,
  live = false,
  height = 380,
  compactPrice = false,
  status = "ready",
  onRetry,
}: MarketChartProps) {
  const reduce = usePrefersReducedMotion();
  const [wrapRef, width] = useElementWidth<HTMLDivElement>();
  const [rangeLabel, setRangeLabel] = React.useState(() => initialRangeLabel(ranges, defaultRange));
  const { ticks, flash } = useLiveTicks(live, data);
  const view = useRangeView(data, ticks, ranges, rangeLabel);
  const n = view.length;

  const layout = React.useMemo(
    () => layoutFor(width, height, showVolume, n),
    [width, height, showVolume, n],
  );
  const { plotX0, step } = layout;
  const cx = React.useCallback((i: number) => plotX0 + step * (i + 0.5), [plotX0, step]);

  const { priceY, priceAt, priceTicks } = usePriceScale(view, variant, reduce, layout);
  const maxVolume = useMaxVolume(view);
  const svgRef = React.useRef<SVGSVGElement | null>(null);
  const { hoverIndex, hoverY, pointerToIndex, clearHover, onKeyDown } = useHover(n, layout, svgRef);
  const summary = usePriceSummary(view, hoverIndex, reduce);
  const timeTicks = useTimeTicks(n, layout);
  const uid = React.useId().replace(/:/g, "");
  const ready = width > 0;
  const { linePath, areaPath, baselineY } = useAreaGeometry(
    view,
    variant,
    reduce,
    layout,
    priceY,
    summary.baseline,
  );

  return (
    <div ref={wrapRef} className={cn("flex w-full flex-col text-muted-foreground/70", className)}>
      <Keyframes />

      <MarketChartHeader
        symbol={symbol}
        name={name}
        live={live}
        reduce={reduce}
        compactPrice={compactPrice}
        price={hoverIndex != null ? (summary.shown?.close ?? 0) : summary.displayPrice}
        delta={summary.delta}
        dirColor={summary.dirColor}
        flash={flash}
        active={summary.active}
        showRangeSelector={showRangeSelector}
        ranges={ranges}
        rangeLabel={rangeLabel}
        onRangeChange={setRangeLabel}
      />

      <ChartState
        status={status}
        height={height}
        variant="bars"
        empty={{
          title: "No price data",
          description:
            "Point the chart at a candle feed and it will render as soon as bars arrive.",
        }}
        onRetry={onRetry}
      >
        <div className="relative w-full" style={{ height }}>
          {!ready ? null : (
            <MarketChartCanvas
              svgRef={svgRef}
              symbol={symbol}
              name={name}
              variant={variant}
              showVolume={showVolume}
              hollowUp={hollowUp}
              live={live}
              reduce={reduce}
              rangeLabel={rangeLabel}
              uid={uid}
              view={view}
              layout={layout}
              cx={cx}
              priceY={priceY}
              priceAt={priceAt}
              priceTicks={priceTicks}
              timeTicks={timeTicks}
              maxVolume={maxVolume}
              summary={summary}
              hoverIndex={hoverIndex}
              hoverY={hoverY}
              pointerToIndex={pointerToIndex}
              clearHover={clearHover}
              onKeyDown={onKeyDown}
              linePath={linePath}
              areaPath={areaPath}
              baselineY={baselineY}
            />
          )}
        </div>
      </ChartState>
    </div>
  );
}
